# Generated by build.py from recipe.yml for recipe smtp-catch-mail-for-unknown-addresses. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'welcome.eml'), "From: app@example.com`nTo: anne@example.com`nSubject: Welcome`n`nYour account is ready.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notice.eml'), "From: app@example.com`nTo: ann@example.com`nSubject: Notice`n`nThe service stops at noon.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mail-domain', 'example.org', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'catchall@example.com:catchpass', '--mailbox', 'team@example.org:teampass', '--mail-catch-all', 'example.com=catchall@example.com', '--mail-alias', 'support@example.com=ann@example.com', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt anne@example.com -T welcome.eml smtp://127.0.0.1:8080/example.com --next --retry 10 --retry-all-errors --retry-delay 1 -u catchall@example.com:catchpass "imap://127.0.0.1:8081/INBOX;UID=1" } finally { Stop-Process $server0 }
